// Разбор подписи: только номер заказ-наряда (буквы, цифры, дефис, 3-32 символа). Другое не принимается.
const m = $json.message;
const cap = String(m.caption || '').trim();
const ok = /^[A-Za-zА-Яа-я0-9-]{3,32}$/.test(cap);
return { json: { ok, order_no: cap, chat_id: m.chat.id, file_id: m.photo[m.photo.length - 1].file_id } };

// SHA-256 исходного файла и шифрование фото AES-256-GCM. Нужны NODE_FUNCTION_ALLOW_BUILTIN=crypto и ARCHIVE_KEY_HEX (64 символа hex).
const crypto = require('crypto');
const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
const keyHex = String($env.ARCHIVE_KEY_HEX || '');
if (!/^[0-9a-fA-F]{64}$/.test(keyHex)) throw new Error('ARCHIVE_KEY_HEX должен быть 64 символа hex');
const sha = crypto.createHash('sha256').update(buf).digest('hex');
const iv = crypto.randomBytes(12);
const c = crypto.createCipheriv('aes-256-gcm', Buffer.from(keyHex, 'hex'), iv);
const enc = Buffer.concat([c.update(buf), c.final()]);
return { json: { image_sha256: sha, enc_hex: enc.toString('hex'), iv_hex: iv.toString('hex'), tag_hex: c.getAuthTag().toString('hex'), size_bytes: buf.length, b64: buf.toString('base64') } };

// Разбор ответа модели. Если ответ не JSON или пустой, серийные номера не выдумываются: запись помечается needs_review.
const prev = $('Хеш и шифрование').item.json;
const cap = $('Разобрать подпись').item.json;
let chips = [];
try {
  const j = JSON.parse(String($json.response || '{}'));
  chips = (Array.isArray(j.chips) ? j.chips : []).map((c) => ({
    component: String(c.component || '').slice(0, 60),
    serial: String(c.serial || '').toUpperCase().replace(/\s+/g, '').slice(0, 40),
    confidence: Math.max(0, Math.min(1, Number(c.confidence) || 0)),
  })).filter((c) => c.serial);
} catch (e) { chips = []; }
const needs = chips.length === 0 || chips.some((c) => c.confidence < 0.8);
return { json: { order_no: cap.order_no, chat_id: cap.chat_id, image_sha256: prev.image_sha256, enc_hex: prev.enc_hex, iv_hex: prev.iv_hex, tag_hex: prev.tag_hex, serials: JSON.stringify(chips), needs_review: needs, chips } };

// Технический акт описи (HTML): номер заказа, серийные номера, SHA-256 фото, хеш записи, время UTC, строки подписей.
const r = $json, p = $('Разобрать ответ').item.json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = p.chips.length ? p.chips.map((c) => `<tr><td>${esc(c.component)}</td><td>${esc(c.serial)}</td><td>${c.confidence.toFixed(2)}</td></tr>`).join('') : '<tr><td colspan="3">серийные номера не распознаны: проверить глазами</td></tr>';
const html = `<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>Акт описи ${esc(p.order_no)}</title><style>body{font-family:sans-serif;max-width:720px;margin:24px auto;padding:0 16px}td,th{border:1px solid #999;padding:6px}table{border-collapse:collapse;width:100%}code{word-break:break-all}</style></head><body>
<h2>Технический акт описи № ${esc(p.order_no)}</h2>
<p>Фотофиксация при вскрытии устройства. Время записи (UTC): <b>${esc(r.ts_utc)}</b>.</p>
<table><tr><th>Компонент</th><th>Серийный номер</th><th>Уверенность</th></tr>${rows}</table>
<p>${p.needs_review ? '<b>Требуется проверка глазами:</b> низкая уверенность распознавания.' : 'Распознавание прошло порог уверенности.'}</p>
<p>SHA-256 фото: <code>${esc(r.image_sha256)}</code></p>
<p>Хеш записи журнала: <code>${esc(r.record_sha256)}</code></p>
<p>Предыдущая запись: <code>${esc(r.prev_record_sha256 || 'нет (первая запись)')}</code></p>
<p style="color:#555;font-size:13px">Хеш подтверждает, что файл фото не менялся после записи. Он не доказывает подлинность момента съёмки и сам по себе не гарантирует юридической силы акта. Согласие клиента на съёмку и форму акта проверьте у юриста.</p>
<p>Клиент: ____________________ Инженер: ____________________</p></body></html>`;
return { json: { act_html: html, order_no: p.order_no, chat_id: p.chat_id, needs_review: p.needs_review, ts_utc: r.ts_utc } };
